<script setup lang="ts">
import { computed } from 'vue'
import { NCheckbox,NButton } from 'naive-ui'
import { CheckCircle2,Info,Video,ShieldCheck } from 'lucide-vue-next'
import type { ChannelSource,Operation,Validation } from '../agents/api'
import type { ParameterDefinition,ParameterSetting,TemplateRevision } from '../agents/templatesApi'
import type { Source } from '../../shared/api/types'
import { label } from '../agents/state'
const props=defineProps<{templateName:string;version:TemplateRevision|null;name:string;bindings:ChannelSource[];sources:Source[];settings:ParameterSetting[];definitions:ParameterDefinition[];validation:Validation|null;operation:Operation|null;expired:boolean;ack:boolean;canAcknowledge:boolean;published:boolean}>()
const emit=defineEmits<{'update:ack':[value:boolean];refresh:[]}>()
const source=(id:string)=>props.sources.find(s=>s.id===id)
const messages=computed(()=>[...(props.validation?.missing_conditions??[]),...(props.validation?.unsupported_conditions??[]),...(props.validation?.evidence_limitations??[])])
const definition=(key:string)=>props.definitions.find(d=>d.key===key)
function value(setting:ParameterSetting){const d=definition(setting.key);return d?.options?.find(o=>o.value===setting.value)?.label??(setting.value==null?'未设置':typeof setting.value==='boolean'?setting.value?'启用':'不启用':String(setting.value))}
</script>
<template>
  <section class="tc-review" aria-label="核对配置与验证结果">
    <header><span class="tc-review-icon"><ShieldCheck :size="25"/></span><div><h2>核对配置与验证结果</h2><p>确认所有视频、监测区域和共用条件后，再启动监测。</p></div></header>
    <div :class="['tc-validation-result',{valid:canAcknowledge}]" role="status"><CheckCircle2 v-if="canAcknowledge" :size="22"/><Info v-else :size="22"/><div><strong>{{expired?'验证已过期':validation?label(validation.verdict):published?'配置已发布':'尚未验证'}}</strong><p>{{canAcknowledge?'配置验证通过，等待你核对并确认启动。':expired?'请返回配置页重新验证，避免使用过期的执行依据。':published&&!validation?'此配置已发布，请到任务详情查看运行状态。':'请根据验证结果完善配置，保存和验证均不会自动启动。'}}</p><ul v-if="messages.length"><li v-for="message in messages" :key="message">{{message}}</li></ul></div></div>
    <div class="tc-review-overview"><div><span>任务名称</span><strong>{{name}}</strong></div><div><span>智能体模板</span><strong>{{templateName}} · 模板版本 v{{version?.revision_no}}</strong></div><div><span>监测视频</span><strong>{{bindings.length}} 路 · 独立监测与报警</strong></div></div>
    <div class="tc-review-columns"><section><h3>逐路视频与区域</h3><article v-for="(b,index) in bindings" :key="b.source_id" class="tc-review-source"><div class="tc-review-source-title"><Video :size="18"/><strong>{{index+1}}. {{source(b.source_id)?.name??b.source_id}}</strong><small>{{source(b.source_id)?.kind==='camera'?'监控直播':'录像文件'}}</small></div><dl><div><dt>监测区域</dt><dd>{{b.regions?.length??0}} 个区域<span v-for="(r,i) in b.regions??[]" :key="r.id" class="tc-review-region">{{r.name||`区域 ${i+1}`}}</span></dd></div><div><dt>监测范围</dt><dd>{{source(b.source_id)?.kind==='camera'?'直播 · 不设录像范围':b.start_media_ms!=null&&b.end_media_ms!=null?`${b.start_media_ms/1000} – ${b.end_media_ms/1000} 秒`:'录像起止位置未设置'}}</dd></div></dl></article></section>
    <section class="tc-review-conditions"><h3>共用检测条件</h3><p>以下条件应用于全部 {{bindings.length}} 路视频，各路分别计时。</p><dl><div v-for="s in settings" :key="s.key"><dt>{{definition(s.key)?.label??s.key}}</dt><dd>{{value(s)}}<small v-if="definition(s.key)?.unit"> {{definition(s.key)?.unit}}</small></dd></div></dl><p v-if="!settings.length">此模板未开放额外配置项。</p></section></div>
    <div class="tc-review-ack"><NCheckbox :checked="ack" :disabled="!canAcknowledge||!!operation" @update:checked="emit('update:ack',$event)">已核对模板版本、视频范围和检测条件</NCheckbox><p>点击下方“确认启动”后，才会发起实际监测。</p></div>
    <section v-if="operation" class="tc-start-result" aria-label="启动操作结果"><h3>{{label(operation.state)}}</h3><p>{{operation.message}}</p><ul><li v-for="c in operation.channels" :key="`${c.channel_id}:${c.source_id}`">{{c.source_id?source(c.source_id)?.name??c.source_id:'监测通道'}} · {{label(c.state)}}<span v-if="c.message"> · {{c.message}}</span></li></ul><NButton size="small" @click="emit('refresh')">刷新启动状态</NButton></section>
  </section>
</template>
<style scoped>
