gion{display:inline-block;padding:2px 7px;border-radius:4px;background:#edf4ff;color:#4777c2;margin-left:7px;font-size:10px}.tc-review-ack{border-top:1px solid #edf1f6;padding-top:20px;margin-top:18px}.tc-review-ack p{font-size:11px;color:#8b99ad;margin:8px 0 0}.tc-start-result{margin-top:20px;padding:17px;background:#f4f7fc;border-radius:6px;font-size:12px;line-height:1.9}.tc-start-result ul{padding-left:18px;margin:12px 0}
